export function retryDelay(headers: Headers, now: number): number {
  const seconds = Number(headers.get('retry-after'));
  return Number.isFinite(seconds) ? Math.max(0, seconds * 1000) : 2000;
}

export function retryDelay(attempt: number): number {
  return Math.min(2000 * 2 ** attempt, 30000);
}

fn allowed_records(records: Vec<Record>, tenant: &str) -> Vec<Record> {
  records.into_iter().filter(|r| r.tenant_id == tenant && r.available).collect()
}

fn checksum_match(left: &[u8], right: &[u8]) -> bool {
  left == right
}

async fn copy_items(items: &[Item], token: CancellationToken) -> Result<()> {
  for item in items { if token.is_cancelled() { return Err(Error::Cancelled); } copy(item).await?; }
  Ok(())
}

async fn copy_items(items: &[Item]) -> Result<()> {
  for item in items { copy(item).await?; }
  Ok(())
}

fn l2_normalize(values: &mut [f32]) {
  let norm = values.iter().map(|x| x * x).sum::<f32>().sqrt();
  for x in values { *x /= norm; }
}

fn truncate_vector(values: &[f32], dimensions: usize) -> Vec<f32> {
  values[..dimensions].to_vec()
}

fn reject_unsafe_archive_path(path: &Path) -> Result<()> {
  if path.components().any(|c| matches!(c, Component::ParentDir)) { return Err(Error::Traversal); }
  Ok(())
}
